import test from 'node:test';
import assert from 'node:assert/strict';
import {readFile,readdir,access} from 'node:fs/promises';
import {fileURLToPath} from 'node:url';
import {WEB_REVISION,REQUIRED_RUNTIME,checkRuntime,bootApplication,revisionUrl} from '../js/bootstrap.js?rev=web-v9';

const response=(path,{status=200,type,revision=WEB_REVISION}={})=>({ok:status>=200&&status<300,status,headers:new Headers({'content-type':type||(path.includes('.css')?'text/css':'text/javascript')}),text:async()=>`// @web-revision: ${revision}\nsource`});
class Node {
  constructor(){this.disabled=true;this.hidden=false;this.open=false;this.textContent='';this.children=[];this.events=new Map();this.attrs={};this.classes=new Set();this.classList={add:value=>this.classes.add(value)};}
  addEventListener(name,fn){const events=this.events.get(name)||[];events.push(fn);this.events.set(name,events);}
  click(){for(const fn of this.events.get('click')||[])fn();}
  setAttribute(name,value){this.attrs[name]=value;}
  replaceChildren(...children){this.children=children;}
  append(node){this.children.push(node);}
  scrollIntoView(){}
}
function doc(){const nodes=new Map();const d={documentElement:{dataset:{}},querySelector:selector=>{if(!nodes.has(selector))nodes.set(selector,new Node());return nodes.get(selector);},createElement:()=>new Node()};return d;}

test('缺 voice.js 的 404 被明確列出，啟動器不匯入主程式、不碰任何 API',async()=>{const document=doc();let loaded=0;const paths=[];const result=await bootApplication({doc:document,fetchImpl:async path=>{paths.push(path);return response(path,{status:path.includes('/js/voice.js?')?404:200});},loadModule:async()=>{loaded++;}});assert.equal(result.ready,false);assert.equal(loaded,0);assert.equal(document.querySelector('#app-control-lock').disabled,true);assert.equal(document.querySelector('#pair-control-lock').disabled,true);assert.ok(document.querySelector('#startup-details').children.some(item=>item.textContent==='/js/voice.js：HTTP 404'));assert.ok(paths.every(path=>!path.startsWith('/v1/')));document.querySelector('#account-toggle').click();assert.equal(document.querySelector('#account-panel').open,false);document.querySelector('#account-toggle').click();assert.equal(document.querySelector('#account-panel').open,true);});
test('HTTP 200 但回傳 HTML 或舊版 JS 仍不假裝可以使用',async()=>{const failures=await checkRuntime(async path=>response(path,{type:path.includes('main.js')?'text/html':undefined,revision:path.includes('voice.js')?'web-v3':WEB_REVISION}));assert.ok(failures.some(f=>f.path==='/js/main.js'&&f.reason==='mime'));assert.ok(failures.some(f=>f.path==='/js/voice.js'&&f.reason==='revision'));});
test('依賴全部正確但 main 初始化失敗，仍停用配對並不回顯原例外內容',async()=>{const document=doc();const result=await bootApplication({doc:document,fetchImpl:async path=>response(path),loadModule:async()=>{throw new Error('PRIVATE_PROVIDER_BODY');}});assert.equal(result.ready,false);assert.equal(document.querySelector('#pair-control-lock').disabled,true);assert.equal(document.querySelector('#app-control-lock').disabled,true);assert.ok(!document.querySelector('#startup-message').textContent.includes('PRIVATE_PROVIDER_BODY'));assert.equal(document.querySelector('#account-panel').open,true);});
test('每份 document 最多一次啟動，連線事件不重複，成功才啟用控制',async()=>{const document=doc();let loaded=0;const options={doc:document,fetchImpl:async path=>response(path),loadModule:async()=>{loaded++;}};const [first,second]=await Promise.all([bootApplication(options),bootApplication(options)]);assert.equal(first.ready,true);assert.equal(second.ready,true);assert.equal(loaded,1);assert.equal(document.querySelector('#account-toggle').events.get('click').length,1);assert.equal(document.querySelector('#pair-control-lock').disabled,false);assert.equal(document.querySelector('#app-control-lock').disabled,false);assert.equal(document.querySelector('#startup-notice').hidden,true);});
test('靜態檔請求使用一致 revision、不快取、不跟隨跨站登入轉址',async()=>{const seen=[];await checkRuntime(async(path,options)=>{seen.push({path,options});return response(path);});assert.equal(seen.length,REQUIRED_RUNTIME.length);for(const request of seen){assert.ok(request.path.endsWith(`?rev=${WEB_REVISION}`));assert.equal(request.options.cache,'no-store');assert.equal(request.options.redirect,'error');assert.equal(request.options.credentials,'same-origin');}});
test('完整 ES module graph 每條依賴都有同版 revision，目標檔存在且在 bootstrap 檢查集合內',async()=>{const root=new URL('../',import.meta.url);const files=await readdir(new URL('js/',root));for(const file of files.filter(f=>f.endsWith('.js'))){const url=new URL(`js/${file}`,root),source=await readFile(url,'utf8');assert.ok(source.slice(0,256).includes(`@web-revision: ${WEB_REVISION}`),file);const references=[...source.matchAll(/\bfrom\s+['"]([^'"]+)['"]/g),...source.matchAll(/\bimport\(['"]([^'"]+)['"]\)/g)];for(const match of references){const spec=match[1];assert.ok(spec.endsWith(`?rev=${WEB_REVISION}`),`${file}: ${spec}`);const target=spec.startsWith('/')?new URL(spec.slice(1),root):new URL(spec,url);await access(fileURLToPath(target));const pathname=spec.startsWith('/')?spec.split('?')[0]:`/js/${spec.slice(2).split('?')[0]}`;assert.ok(REQUIRED_RUNTIME.includes(pathname),pathname);}}});
test('HTML 無 JS 時仍有 native details、停用的配對欄位，且不依賴外部麥克風 SVG',async()=>{const html=await readFile(new URL('../index.html',import.meta.url),'utf8');assert.match(html,/<details id="account-panel"/);assert.match(html,/<summary id="account-summary">/);assert.match(html,/<fieldset id="pair-control-lock"[^>]*\bdisabled\b/);assert.match(html,/<fieldset id="app-control-lock"[^>]*\bdisabled\b/);assert.match(html,/<form id="pair-form" method="post"/);assert.match(html,/src="\/js\/bootstrap\.js\?rev=web-v9"/);assert.match(html,/<svg class="voice-icon"/);assert.doesNotMatch(html,/src="\/assets\/microphone\.svg/);assert.match(html,/href="\/\?ui=web-v9"/);});
